  mouth:{name:'CORROSIVE MEMORY',desc:'ACID DAMAGE +3% PER RANK',short:'ACID DAMAGE'},
  tail:{name:'RAZOR MEMORY',desc:'TAIL DAMAGE +3% PER RANK',short:'TAIL DAMAGE'},
