function updateLab(){
  $('metaDNA').textContent=meta.dna;renderOrigins();renderUnlockTree();renderNemesisStatus(true);renderMemoryArchive();renderCampaignTrack();const stageNow=meta.stage||1,milNow=campaignMilestone(stageNow);if($('campaignStats'))$('campaignStats').textContent='STAGE '+stageNow+' · '+stageThreatText(stageNow)+' · CLEAR '+(meta.clears||0)+' · APEX GENE '+(meta.apexGenes||0);if($('heroStage'))$('heroStage').textContent='STAGE '+stageNow+' · CLEAR '+(meta.clears||0);if($('heroRoute'))$('heroRoute').textContent=meta.route==='cryo'?'CRYO VAULT':meta.route==='gene'?'GENE TEMPLE':meta.route==='inferno'?'INFERNO HIVE':'CELL ORIGIN';if($('heroThreat')){$('heroThreat').textContent=(milNow?milNow+' · ':'')+stageThreatText(stageNow);$('heroThreat').className=milNow==='OMEGA'?'omega':milNow==='APEX'?'apex':'';}
  const defs=[
    {id:'labHp',key:'hp',name:'CELL DENSITY',desc:'MAX HP +5%',max:5,unlock:0,base:24},
    {id:'labDmg',key:'dmg',name:'PREDATOR GENES',desc:'DAMAGE +4%',max:5,unlock:0,base:30},
    {id:'labPickup',key:'pickup',name:'ABSORPTION',desc:'PICKUP +10',max:5,unlock:0,base:20},
    {id:'labSpeed',key:'speed',name:'MOTOR NERVES',desc:'MOVE SPEED +3%',max:5,unlock:1,base:27},
    {id:'labArmor',key:'armor',name:'CARAPACE MEMORY',desc:'DAMAGE TAKEN -3%',max:5,unlock:2,base:34},
    {id:'labReroll',key:'reroll',name:'RECOMBINATION',desc:'START REROLL +1',max:3,unlock:3,base:72}
  ];
  for(const d of defs){
    let b=$(d.id),r=meta[d.key]||0,locked=(meta.clears||0)<d.unlock,c=metaCost(r,d.base);
    let rank=r>=d.max?'MAX':'Lv.'+r;
    let extra=locked?('CLEAR '+d.unlock+' STAGE'+(d.unlock>1?'S':'')+' TO UNLOCK'):(r>=d.max?'MAXED':c+' DNA');
    b.innerHTML='<b>'+d.name+' · '+rank+'</b><span>'+d.desc+' · '+extra+'</span>';
    b.disabled=locked||r>=d.max||meta.dna<c;b.classList.toggle('affordable',!b.disabled&&meta.dna>=c);
    b.onclick=()=>{if((meta.clears||0)<d.unlock||meta[d.key]>=d.max)return;let cost=metaCost(meta[d.key]||0,d.base);if(meta.dna<cost)return;meta.dna-=cost;meta[d.key]=(meta[d.key]||0)+1;saveMeta();updateLab();beep(700,.08,'triangle',.025);};
  }
}
