function updatePredationHUD(){
  const wrap=$('predationWrap'),fill=$('predationFill'),label=$('predationLabel');
  if(frenzy>0){
    wrap.classList.add('frenzy');fill.style.width='100%';
    label.textContent='FEEDING FRENZY · '+frenzy.toFixed(1)+'s · CHAIN '+killChain;
  }else{
    wrap.classList.remove('frenzy');fill.style.width=clamp(predation,0,100)+'%';
    label.textContent='PREDATION '+Math.floor(predation)+'%'+(killChain>1?' · CHAIN '+killChain:'');
  }
}
function triggerPredation(){
  if(frenzy>0)return;
  predation=0;frenzy=6.0;player.inv=Math.max(player.inv,.22);cameraShake=Math.max(cameraShake,8);
  announceEncounter('FEEDING FRENZY','DAMAGE +20% · SPEED +14% · RAPID ATTACK');
  flash('PREDATION OVERDRIVE',1100);beep(72,.18,'sawtooth',.04);setTimeout(()=>beep(118,.16,'sawtooth',.03),90);
  for(let i=0;i<34;i++)particles.push({kind:'frenzy',x:player.x,y:player.y,vx:rand(-120,120),vy:rand(-120,120),r:rand(1.5,4.5),life:rand(.3,.8)});
}
function gainPredation(v){
  if(evoForm.speed==='hunt')v*=1.35;
  if(frenzy>0){frenzy=Math.min(8,frenzy+v*.018);return}
  predation=Math.min(100,predation+v);
  if(predation>=100)triggerPredation();
}
