    ctx.globalAlpha=.12;ctx.strokeStyle=accent;ctx.beginPath();ctx.moveTo(W*.08,y);ctx.lineTo(W*.20,y);ctx.stroke();
    ctx.beginPath();ctx.moveTo(W*.80,y+38);ctx.lineTo(W*.92,y+38);ctx.stroke();
    ctx.globalAlpha=.28;ctx.fillStyle=accent;ctx.fillRect(W*.075,y-2,6,4);ctx.fillRect(W*.915,y+36,6,4);
