  const local=preferred&&i<240,a=rand(0,TAU),rr=rand(16,Math.min(280,30+i));
  const p=local?{x:preferred.x+Math.cos(a)*rr,y:preferred.y+Math.sin(a)*rr}:{x:rand(q.x+r+28,q.x+q.w-r-28),y:rand(q.y+r+28,q.y+q.h-r-28)};
  if(valid(p))return p;
