function worldSiteLabel(s){return s.type==='bioChest'?'KNOWLEDGE CAPSULE':s.type==='regen'?'HEALTH CAPSULE':s.type==='shield'?'SHIELD CAPSULE':s.type==='rift'?'GENE CAPSULE':s.type==='hotspot'?'RELIC CHALLENGE':s.type==='zoneEvent'?zoneEventDef(s).site:'BIOHAZARD'}
