    e.x=clamp(s.x+Math.cos(a)*rr,28,WORLD_W-28);e.y=clamp(s.y+Math.sin(a)*rr,28,WORLD_H-28);resolveTerrainBody(e,e.r);e.worldSiteId=s.id;e.worldHotspot=true;e.zoneEventAdd=true;e.spawnFx=.46;
