      lead.barrierMax=Math.max(lead.barrierMax||0,lead.maxHp*.105);lead.barrier=Math.min(lead.barrierMax,Math.max(lead.barrier||0,lead.maxHp*.085));particles.push({kind:'supportPulse',x:lead.x,y:lead.y,r:8,max:lead.r+48,life:.40,maxLife:.40,color:'shield'});s.eventTick=3.2;
