function updateWorldSites(dt){
 worldSiteHintCd=Math.max(0,worldSiteHintCd-dt);
 for(const s of worldSites){
  s.pulse+=dt*3;if(s.claimed||s.arenaHidden)continue;
  if(s.active){if(s.type==='zoneEvent')updateZoneEventSite(s,dt);continue;}
  const d=Math.hypot(player.x-s.x,player.y-s.y),inside=d<=s.r;
  const encounter=s.type==='hotspot'||s.type==='zoneEvent'||s.type==='rift';
  const locked=encounter&&!directorCanStart('rift'),full=s.type==='regen'&&player.hp>=player.maxHp;
  if(inside&&!locked&&!full)s.hold=Math.min(s.need,s.hold+dt);else s.hold=Math.max(0,s.hold-dt*.8);
  if(s.hold<s.need||locked||full)continue;
  if(s.type==='hotspot'){activateHotspot(s);s.initialCount=s.remaining;}
  else if(s.type==='zoneEvent'){activateZoneEvent(s);s.initialCount=s.remaining;}
  else if(s.type==='rift'){if(spawnGeneRift(1,s))completeGeneRift();}
  else completeWorldSite(s);
 }
}
