 if(near||active){let status=active?'DEFEAT '+s.remaining+' · CLAIM REWARD':s.type==='regen'&&player.hp>=player.maxHp?'HP FULL':locked?'LOCKED · ENCOUNTER':q>0?Math.floor(q*100)+'%':s.type==='zoneEvent'||s.type==='hotspot'?'HOLD TO START CHALLENGE':'STAND INSIDE TO ABSORB';ctx.font='700 5.5px system-ui';ctx.fillStyle='#edf6ff';ctx.strokeText(status,s.x,s.y+s.r+19);ctx.fillText(status,s.x,s.y+s.r+19);}
 ctx.restore();
