    if(inside&&z.kind==='cryo'){let slow=.22*(1-Math.min(.40,routeMods.cryoResist||0));player.envSlow=Math.max(player.envSlow,slow);}
    if(inside&&z.kind==='magma'&&z.tick<=0){let heat=Math.max(3,(8+Math.min(12,Math.max(0,meta.stage-1)))*(1-Math.min(.18,routeMods.heatResist||0)));playerDamage(heat);z.tick=.42;cameraShake=Math.max(cameraShake,2.5);}
