    tacticalWave.cleared=true;waveClears++;let elapsed=(tacticalWave.startTime||18)-tacticalWave.time,rapid=elapsed<=9.5,reward=8+Math.min(8,meta.stage||1)+(tacticalWaveIndex>=3?2:0)+(rapid?4:0);tacticalWave.reward=reward;tacticalWave.rapid=rapid;if(rapid)rapidWaveClears++;dnaTotal+=reward;predation=Math.min(100,predation+(rapid?22:16));player.hp=Math.min(player.maxHp,player.hp+(rapid?9:6));activeReady=Math.max(0,activeReady-(rapid?1.0:.7));announceEncounter(rapid?'RAPID DOMINATION':'WAVE DOMINATED',(rapid?'FAST CLEAR · ':'TACTICAL CLEAR · ')+'DNA +'+reward);flash(rapid?'RAPID CLEAR · PREDATION +22%':'DOMINATED · PREDATION +16%',820);cameraShake=Math.max(cameraShake,rapid?7:5);beep(rapid?860:740,.08,'triangle',.028);updateWaveBadge();
