  if(coachStep===0&&t>.55){coachStep=1;coachHint(coarsePointer?'MOVE · TOUCH ANYWHERE & DRAG':'MOVE · WASD / ARROW KEYS',4.2);updateCoachVisuals()}
  else if(coachStep===1&&(player.moveBlend||0)>.38){coachStep=2;coachHint(coarsePointer?'DASH · TAP ➤ TO EVADE':'DASH · SPACE TO EVADE',4.0);updateCoachVisuals()}
  else if(coachStep===2&&t>18&&focusHintTimer<=0)coachHint(coarsePointer?'DASH · TAP ➤ TO EVADE':'DASH · SPACE TO EVADE',3.2);
