function hurtEnemy(e,dmg,kind){
  const bridge=window.EVOLVE_HIT_EVENTS;
  weaponHitConnectV612(bridge);organHitConnectV613(bridge);
  if(!e||!bridge||!bridge._active())return hurtEnemyCoreV601(e,dmg,kind);
  const before={hp:Number.isFinite(e.hp)?e.hp:0,barrier:Number.isFinite(e.barrier)?e.barrier:0,
    kx:Number.isFinite(e.kx)?e.kx:0,ky:Number.isFinite(e.ky)?e.ky:0,dead:!!e.dead};
  const result=hurtEnemyCoreV601(e,dmg,kind);
  const oldTargetV612=weaponHitTargetV612;weaponHitTargetV612=e;
  try{bridge._record(e,dmg,kind,before,typeof t==='number'?t:null,(kind==='arm'||kind==='artillery')?weaponHitSourceV612:null);}catch(_){/* Never alter combat results. */}finally{weaponHitTargetV612=oldTargetV612;}
  return result;
}

