 if(state.leg>0){addPart('leg',-bodySize*.13,bodySize*.24,bodySize*(.30+state.leg*.018),-.12,.72);addPart('leg',bodySize*.04,bodySize*.24,bodySize*(.30+state.leg*.018),.12,.72);}
