    if(e.finalBoss){minimapDiamond(p,'#ffd160',12,2);minimapDot(p,'#541c18',7,0,1);c.fillStyle='#fff4db';c.font='900 10px system-ui';c.textAlign='center';c.textBaseline='middle';c.fillText('B',p.x,p.y+.5);}
    else minimapDot(p,color,major?7.5+pulse:3.0,major?3:0,1);
