  c.strokeStyle='#fff9';c.lineWidth=1.1;c.beginPath();c.arc(cx,cy,10,0,TAU);c.stroke();
  minimapTriangle({x:cx,y:cy},'#f4ffff',7.2,player.look||0,3);
  c.restore();
  wrap.classList.toggle('bossTrack',nearBoss);wrap.classList.toggle('nemesisTrack',!nearBoss&&nearNemesis);
