function stageUnlockFromSaveV522(m){
 let best=Math.max(1,m.stage|0||1,m.unlockedStageV522|0||1);
 if(Array.isArray(m.claimedStages))for(const s of m.claimedStages){if(Number.isInteger(s)&&s>=1&&s<=99)best=Math.max(best,Math.min(99,s+1));}
 return best;
}
