  ctx.save();ctx.translate(enemy.x,enemy.y+p.bob);ctx.rotate(p.rot);ctx.scale(p.sx,p.sy);ctx.translate(-enemy.x,-enemy.y);
  try{return organHitEnemyBaseV613(enemy,shadowOnly);}finally{ctx.restore();}
